import { Directive, signal } from '@angular/core';
import { ControlValueAccessor } from '@angular/forms';

/** Base ControlValueAccessor dùng chung cho form control wrapper (hrm-input,
 *  hrm-select, hrm-checkbox...). Component con extends + khai NG_VALUE_ACCESSOR,
 *  template bind giá trị nội bộ vào ng-zorro control, gọi emit() khi đổi. */
@Directive()
export abstract class HrmControl<T> implements ControlValueAccessor {
  /** giá trị hiện tại (signal — bind trong template) */
  readonly value = signal<T | null>(null);
  readonly disabled = signal(false);

  private _onChange: (v: T | null) => void = () => {};
  protected _onTouched: () => void = () => {};

  writeValue(v: T | null): void { this.value.set(v); }
  registerOnChange(fn: (v: T | null) => void): void { this._onChange = fn; }
  registerOnTouched(fn: () => void): void { this._onTouched = fn; }
  setDisabledState(isDisabled: boolean): void { this.disabled.set(isDisabled); }

  /** con gọi khi user đổi giá trị */
  protected emit(v: T | null): void {
    this.value.set(v);
    this._onChange(v);
  }

  protected markTouched(): void { this._onTouched(); }
}
